record AccountKey(long tenantId, long accountId) {}
var cache = new java.util.HashMap<AccountKey, String>();
cache.put(new AccountKey(10, 1), "账户信息");
System.out.println(cache.get(new AccountKey(10, 1))); // 账户信息

